#include <bits/stdc++.h>
using namespace std;

using LL = long long;

const int MAXN = 32;
const int MAXB = 60;
const int MOD = 1000000007;
const LL INF = 2000000000000000000LL;

inline void reduce(int &x)
{
    if (x >= MOD) x -= MOD;
    if (x < 0) x += MOD;
}

struct Matrix
{
    int data[MAXN][MAXN];
    int size;
    Matrix(int n=0, int val=0)
    {
        size = n;
        for (int i=0; i<size; i++)
            for (int j=0; j<size; j++)
                data[i][j] = (i==j)? val : 0;
    }
    int* operator[](int i) { return data[i]; }
    Matrix operator*(const Matrix &b)
    {
        Matrix res(size, 0);
        for (int i=0; i<size; i++)
            for (int j=0; j<size; j++)
                for (int k=0; k<size; k++)
                    reduce(res[i][k] += (LL)data[i][j] * b[j][k] % MOD);
        return res;
    }
    Matrix operator+(const Matrix &b)
    {
        Matrix res(size, 0);
        for (int i=0; i<size; i++)
            for (int j=0; j<size; j++)
                res[i][j] = data[i][j] + b[i][j];
        return res;
    }
    bool operator==(const Matrix &b)
    {
        if (size != b.size) return false;
        for (int i=0; i<size; i++)
            for (int j=0; j<size; j++)
                if (data[i][j] != b[i][j]) return false;
        return true;
    }
};

Matrix powerMatrix(Matrix base, LL exp)
{
    Matrix res(base.size, 1);
    while (exp)
    {
        if (exp & 1) res = res * base;
        base = base * base;
        exp >>= 1;
    }
    return res;
}

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);

    LL n;
    int k;
    cin >> n >> k;

    vector<LL> val(MAXB, 1);
    int lastIdx = MAXB;
    for (int i=1; i<MAXB; i++)
    {
        if (val[i-1] >= INF / k)
        {
            val[i] = INF;
            lastIdx = i;
            break;
        }
        val[i] = val[i-1] * k;
    }

    vector<Matrix> shift(MAXB, Matrix(k+1));
    shift[0] = Matrix(k+1, 1);
    shift[1] = Matrix(k+1);
    for (int i=0; i<k; i++)
