    shift[1][k][k] = 1;

    for (int i=2; i<k; i++)
        shift[i] = shift[i-1] * shift[1];

    vector<Matrix> a(MAXB, Matrix(k+1));
    for (int i=0; i<=k; i++)
        a[0][i][0] = 1;

    for (int i=1; i<lastIdx; i++)
    {
        Matrix tmp = a[i-1];
        a[i] = a[i-1];
        for (int j=1; j<k; j++)
        {
            a[i] = a[i] * shift[k-1];
            a[i] = a[i] * tmp;
        }
        a[i] = a[i] * shift[k-1];
    }

    Matrix answer(k+1);
    answer[0][k] = 1;
    answer = answer * get(n, lastIdx - 1);

    int res = 0;
    for (int i=0; i<=k; i++)
        reduce(res += answer[0][i]);

    cout << res << "\n";
}
